-- =============================================================================
-- RISE NETWORK — Migration 4: slug default
-- The slug is always generated by the opportunities_set_slug trigger. Declaring a
-- column default makes that explicit, so clients (which have no INSERT privilege on
-- slug) can insert without supplying it and generated API types mark it optional.
-- =============================================================================
alter table public.opportunities alter column slug set default '';

comment on column public.opportunities.slug is
  'Generated by trigger opportunities_set_slug (title + 8 chars of id). Never supplied by clients.';
